from autopkglib import ProcessorError, URLGetter
import re

__all__ = ["ZuluJDKv2ReleaseProvider"]

apiBaseUrl = "https://api.azul.com/zulu/download/community/v1.0/bundles/latest/binary"

# Munki installcheck_script template.
# Placeholders (@@...@@) are replaced in main(); no %-escaping needed.
CHECK_TEMPLATE = r'''#!/bin/bash
# Munki installcheck_script - generated by ZuluJDKv2ReleaseProvider
# Exit 0 = install, Exit 1 = up-to-date

MAINVERSION="@@MAINVERSION@@"
NEWVERSION="@@NEWVERSION@@"
NEWZULU="@@NEWZULU@@"

# Compare dotted versions with any number of fields. Returns 0 if $1 > $2
version_gt() {
  local IFS=.
  local -a a=($1) b=($2)
  local i n=$(( ${#a[@]} > ${#b[@]} ? ${#a[@]} : ${#b[@]} ))
  for ((i=0; i<n; i++)); do
    local x=$((10#${a[i]:-0})) y=$((10#${b[i]:-0}))
    (( x > y )) && return 0
    (( x < y )) && return 1
  done
  return 1
}

if ! JAVAHOME=$(/usr/libexec/java_home -F -v "${MAINVERSION}" 2>/dev/null); then
  echo "No Java ${MAINVERSION} installed."
  exit 0
fi

RELEASE="${JAVAHOME}/release"

# OpenJDK version: release file first (no JVM start), fallback java -version
INSTALLEDVERSION=$(awk -F'"' '/^JAVA_VERSION=/{print $2}' "$RELEASE" 2>/dev/null)
[[ -z "$INSTALLEDVERSION" ]] && \
  INSTALLEDVERSION=$("${JAVAHOME}/bin/java" -version 2>&1 | awk -F'"' 'NR==1{print $2}')
# 1.8.0_472 -> 1.8.0.472, strip suffixes like -ea
INSTALLEDVERSION=$(echo "$INSTALLEDVERSION" | tr '_' '.' | sed 's/[^0-9.].*//')

# Zulu build: "Zulu25.38+109-CA" -> 25.38.109 (empty for non-Zulu JDKs)
INSTALLEDZULU=$(awk -F'"' '/^IMPLEMENTOR_VERSION=/{print $2}' "$RELEASE" 2>/dev/null \
  | sed -nE 's/^Zulu([0-9.+]+).*/\1/p' | tr '+' '.' | sed 's/\.$//')

echo "JAVA_HOME: ${JAVAHOME}"
echo "JDK  installed=${INSTALLEDVERSION:-n/a}  new=${NEWVERSION}"
echo "Zulu installed=${INSTALLEDZULU:-n/a}  new=${NEWZULU:-n/a}"

# 1. OpenJDK version is newer
if version_gt "$NEWVERSION" "$INSTALLEDVERSION"; then
  echo "Newer JDK version available."
  exit 0
fi

# 2. Same OpenJDK version, but newer Zulu build (repackage)
if [[ -n "$NEWZULU" && -n "$INSTALLEDZULU" ]] \
   && ! version_gt "$INSTALLEDVERSION" "$NEWVERSION" \
   && version_gt "$NEWZULU" "$INSTALLEDZULU"; then
  echo "Newer Zulu build available."
  exit 0
fi

echo "Installed version is up-to-date."
exit 1
'''


class ZuluJDKv2ReleaseProvider(URLGetter):
    description = "Finds the latest Zulu OpenJDK and builds a Munki installcheck_script."
    input_variables = {
        "JAVA_VERSION": {
            "required": True,
            "description": "A valid major version like 8, 11 or 17.",
        },
        "JAVA_ARCH": {
            "required": True,
            "description": "A valid architecture like arm or x86.",
        }
    }
    output_variables = {
        "url": {
            "description": "URL to the latest Zulu OpenJDK for given version and architecture."
        },
        "JDK_CHECK": {
            "description": "Install Check Script."
        },
        "JDK_VERSION": {
            "description": "Version of the latest Zulu OpenJDK for given version and architecture."
        },
        "ZULU_VERSION": {
            "description": "Azul Zulu build version, e.g. 25.38.109."
        },
        "MUNKI_ARCHITECTURE": {
            "description": "Architecture needed by munki for this release: arm64 or x86_64."
        }
    }

    def main(self):
        # Azul API returns a redirect to the latest release
        apiCall = "%s/?java_version=%s&os=macos&arch=%s&ext=dmg&release_status=ga&bundle_type=jdk&javafx=false" % (
            apiBaseUrl, self.env["JAVA_VERSION"], self.env["JAVA_ARCH"]
        )
        self.output("Get latest Version from api with: %s" % apiCall)
        curl_cmd = [self.curl_binary(), apiCall]
        redirectRequest = self.download_with_curl(curl_cmd, text=True)

        # URLGetter doesn't return headers, so parse the redirect body
        match = re.search(r'href=[\'"]?([^\'" >]+)', redirectRequest)
        if not match:
            raise ProcessorError("No redirect found for latest Zulu JDK %s for arch %s" % (
                self.env["JAVA_VERSION"], self.env["JAVA_ARCH"]
            ))

        downloadUrl = match.group(1)
        (baseUrl, jdkFilename) = downloadUrl.rsplit("/", 1)

        # e.g. zulu25.38.109-ca-jdk25.0.5.0.3-macosx_aarch64.dmg
        #   azulVersion    -> zulu25.38.109-ca
        #   jdkVersionTemp -> jdk25.0.5.0.3
        #   binaryTyp      -> macosx_aarch64.dmg
        (azulVersion, jdkVersionTemp, binaryTyp) = jdkFilename.rsplit("-", 2)
        jdkVersion = jdkVersionTemp[3:]
        jdkCheckVersion = jdkVersion
        (jdkMajor, jdkMinor, jdkPatch) = jdkVersion.split(".", 2)

        zuluMatch = re.match(r'zulu([\d.]+)', azulVersion, re.IGNORECASE)
        zuluVersion = zuluMatch.group(1).rstrip(".") if zuluMatch else ""
        if not zuluVersion:
            self.output("WARNING: Could not parse Zulu version from %s" % azulVersion)

        # JDK8 version numbering differs
        if self.env["JAVA_VERSION"] == "8":
            jdkVersion = "1.8.%s" % jdkPatch
            jdkCheckVersion = "1.8.0.%s" % jdkPatch
            jdkMajor = "1.8"

        jdkCheckScript = (
            CHECK_TEMPLATE
            .replace("@@MAINVERSION@@", jdkMajor)
            .replace("@@NEWVERSION@@", jdkCheckVersion)
            .replace("@@NEWZULU@@", zuluVersion)
        )

        self.output(" Latest Open JDK %s for %s" % (
            self.env["JAVA_VERSION"], self.env["JAVA_ARCH"]
        ))
        self.output(" Version     : %s" % jdkVersion)
        self.output(" Check Ver.  : %s" % jdkCheckVersion)
        self.output(" Zulu Version: %s" % (zuluVersion or azulVersion))
        self.output(" URL         : %s" % downloadUrl)

        self.env["url"] = downloadUrl
        self.env["JDK_VERSION"] = jdkVersion
        self.env["ZULU_VERSION"] = zuluVersion
        self.env["JDK_CHECK"] = jdkCheckScript
        if self.env["JAVA_ARCH"] == "arm":
            self.env["MUNKI_ARCHITECTURE"] = "arm64"
        elif self.env["JAVA_ARCH"] == "x86":
            self.env["MUNKI_ARCHITECTURE"] = "x86_64"
        else:
            raise ProcessorError("Unknown JAVA_ARCH: %s" % self.env["JAVA_ARCH"])


if __name__ == "__main__":
    PROCESSOR = ZuluJDKv2ReleaseProvider()
    PROCESSOR.execute_shell()